(function(pluginName, message) {
  tinymce.PluginManager.add(pluginName, function(editor) {
      editor.on("skinLoaded", function() {
          if (!editor.getParam('service_message')) {
            editor.notificationManager.open({
                text: message,
                type: 'warning'
            });
          }
      });

      return {
        isStub: true
      };
  });
})("rtc", "The rtc premium plugin is not enabled on your API key. \u003ca target=\"_blank\" href=\"https://www.tiny.cloud/pricing/?utm_source=tinymce\u0026amp;utm_medium=notification\u0026amp;utm_campaign=ubb_no_api_key\"\u003eUpgrade your account\u003c/a\u003e.");
